from itertools import permutations
nodes=['a','b','c']
for mask in range(64):
 edges=[(a,b) for a in nodes for b in nodes if a!=b]
 graph={a:[] for a in nodes}
 for bit,(a,b) in enumerate(edges):
  if mask & (1<<bit): graph[a].append(b)
 orders=[list(p) for p in permutations(nodes) if all(p.index(b)<p.index(a) for a in nodes for b in graph[a])]
 for mapping in [graph,dict(reversed(list(graph.items())))]:
  if orders: assert f(mapping)==min(orders)
  else:
   try: f(mapping)
   except ValueError: pass
   else: raise AssertionError('cycle accepted')

